<?php
function om_bulk_date_plan($id,$ids,$date,$reason,$lock=false){
 om_require();$date=process_date($date);$reason=process_reason($reason);if($date>date('Y-m-d'))throw new Exception('Fulfillment date cannot be in the future.');
 if(!is_array($ids))throw new Exception('Invalid order selection.');foreach($ids as $oid)if(!is_scalar($oid)||!ctype_digit((string)$oid))throw new Exception('Invalid order selection.');$ids=array_values(array_unique(array_map('intval',$ids)));sort($ids,SORT_NUMERIC);if(!$ids||count($ids)>5000||min($ids)<1)throw new Exception('Select 1 to 5000 orders from this upload.');
 if($lock)om_query('SELECT id FROM om_uploads WHERE id=? FOR UPDATE',[$id])->fetch();$b=om_upload($id);om_owner($b);if($b['kind']!=='Status')throw new Exception('Use an unconfirmed status upload.');
 $groups=[];foreach($b['rows'] as $line)$groups[(string)$line['order']][]=$line;$rows=[];
 foreach($ids as $oid){$row=['id'=>$oid,'order'=>'#'.$oid,'before'=>'','revision'=>0,'error'=>''];try{$o=om_order($oid,$lock);$row['order']=$o['order_no'];$row['before']=$o['fulfillment_date'];$row['revision']=(int)$o['revision'];
  if($o['platform']!==$b['platform']||$o['shop']!==$b['shop']||!isset($groups[$o['order_no']]))throw new Exception('Order does not belong to this source upload.');
  if(oi_exclusion($b,$o['order_no']))throw new Exception('Order was removed from this upload. Restore it before correcting dates.');
  if($o['posting']!=='Not Posted'||om_query('SELECT COUNT(*) FROM om_postings WHERE order_id=?',[$oid])->fetchColumn())throw new Exception('Posted / reversed orders cannot be changed here.');
  if(access_profile()!=='Admin'&&(int)$o['owner_id']!==current_user()['id'])throw new Exception('Only the original registration owner or Admin can correct this order.');
  if($date<substr($o['created_order_at'],0,10))throw new Exception('New fulfillment date precedes order creation.');if($date===$o['fulfillment_date'])throw new Exception('Already on the selected fulfillment date.');
  $lines=$groups[$o['order_no']];om_validate_source_dates($lines,$b['meta'],'Status');$details=om_date_details($lines,$o,$b['meta']);foreach($details['shipping_dates'] as $ship)if(substr($ship,0,10)<$date)throw new Exception('Shipping date precedes the proposed fulfillment date.');require_open_inventory_date($date);
 }catch(Throwable $e){$row['error']=$e->getMessage();}$rows[]=$row;}
 $plan=['upload_id'=>(int)$id,'upload_revision'=>(int)$b['revision'],'user_id'=>current_user()['id'],'date'=>$date,'reason'=>$reason,'rows'=>$rows];$plan['digest']=hash('sha256',json_encode($plan));return $plan;
}
function om_bulk_date_apply($saved){return process_transaction(function()use($saved){$fresh=om_bulk_date_plan($saved['upload_id'],array_column($saved['rows'],'id'),$saved['date'],$saved['reason'],true);if(!hash_equals($saved['digest'],$fresh['digest']))throw new Exception('Orders or upload changed. Validate the selection again.');if(array_filter($fresh['rows'],fn($r)=>$r['error']!==''))throw new Exception('Resolve or unselect blocked rows and validate again. No date changed.');foreach($fresh['rows'] as $r)om_correct_fulfillment($fresh['upload_id'],$r['id'],$r['revision'],$fresh['date'],$fresh['reason']);om_event(null,$fresh['upload_id'],'Bulk fulfillment dates corrected',['orders'=>array_column($fresh['rows'],'order'),'date'=>$fresh['date'],'reason'=>$fresh['reason'],'stock_changed'=>false]);return count($fresh['rows']);});}
function om_bulk_date_panel($b,$rows){
 if($b['kind']!=='Status'||$b['status']!=='Review'||!om_allowed()||(access_profile()!=='Admin'&&(int)$b['created_by']!==current_user()['id']))return;
 $saved=$_SESSION['om_bulk_dates'][$b['id']]??null;echo '<style>.om-bulk-date input[type=checkbox]{width:16px;height:16px;min-height:16px;margin:0 8px 0 0}.om-bulk-date label{margin:10px 0}</style><details class="om-correction om-bulk-date"'.($saved?' open':'').'><summary>Bulk Correct Fulfillment Date</summary><p>Select only orders actually fulfilled on the same date. Validation and date correction do not post stock. Confirm status updates separately afterward.</p>';
 if($saved){$plan=$saved['plan'];echo '<h3>Correction Preview</h3><p>New date: <b>'.e($plan['date']).'</b> · Reason: '.e($plan['reason']).'</p><div class="om-table"><table class="table" data-server-paginated="1"><tr><th>Order ID</th><th>Current Date</th><th>New Date</th><th>Validation</th></tr>';foreach($plan['rows'] as $r)echo '<tr><td>'.e($r['order']).'</td><td>'.e($r['before']).'</td><td>'.e($plan['date']).'</td><td>'.e($r['error']?:'Eligible · no stock movement').'</td></tr>';echo '</table></div>';
  if(!array_filter($plan['rows'],fn($r)=>$r['error']!=='')){om_form('om_bulk_date_apply',['upload_id'=>$b['id'],'bulk_token'=>$saved['token']]);echo '<label class="om-inline"><input type="checkbox" name="bulk_ack" value="1" required> I verified the actual fulfillment date for every selected order.</label><button class="btn primary">Apply Corrections &amp; Revalidate</button></form>';}else echo '<p class="alert warn">Unselect blocked orders or correct the proposed date, then validate again. Nothing has changed.</p>';
 }
 om_form('om_bulk_date_validate',['upload_id'=>$b['id'],'selection_json'=>'[]']);echo '<label>Actual Fulfillment Date<input type="date" name="fulfillment_date" max="'.date('Y-m-d').'" value="'.e($saved['plan']['date']??date('Y-m-d',strtotime('-1 day'))).'" required></label><label>Shared reason / supporting reference<input name="reason" minlength="3" value="'.e($saved['plan']['reason']??'').'" required></label><label class="om-inline"><input type="checkbox" data-bulk-select-all> Select All Eligible Orders (all review pages)</label><label class="om-inline"><input type="checkbox" data-bulk-select-affected> Select only orders with fulfillment-date errors</label><p class="small muted" data-bulk-selection aria-live="polite"></p><div class="om-table"><table class="table" data-server-paginated="1"><tr><th>Select</th><th>Order ID</th><th>Current Fulfillment</th><th>Eligibility</th></tr>';
 $seen=[];foreach($rows as $r){$o=$r['order_record']??null;if(!$o||isset($seen[$o['id']])||!$r['lines']||$r['action']==='Removed from Upload')continue;$seen[$o['id']]=true;$eligible=$o['posting']==='Not Posted'&&!om_query('SELECT COUNT(*) FROM om_postings WHERE order_id=?',[$o['id']])->fetchColumn()&&(access_profile()==='Admin'||(int)$o['owner_id']===current_user()['id']);$affected=(bool)array_filter($r['errors'],fn($e)=>str_contains($e,'Fulfillment Date'));$selected=$saved&&in_array((int)$o['id'],array_column($saved['plan']['rows'],'id'),true);echo '<tr><td><input type="checkbox" value="'.(int)$o['id'].'" data-bulk-order data-affected="'.($affected?'1':'0').'" aria-label="Select '.e($o['order_no']).'" '.(!$eligible?'disabled':'').($selected?' checked':'').'></td><td>'.e($o['order_no']).'</td><td>'.e($o['fulfillment_date']).'</td><td>'.e($eligible?($affected?'Fulfillment-date issue':'Unposted · select only if date is wrong'):'Posted / reversed or another owner').'</td></tr>';}
 echo '</table></div><button class="btn secondary">Validate Bulk Correction</button></form></details><script>document.querySelectorAll("[data-bulk-select-all]").forEach(function(all){const form=all.form,affected=form.querySelector("[data-bulk-select-affected]"),summary=form.querySelector("[data-bulk-selection]"),rows=Array.from(form.querySelectorAll("[data-bulk-order]:not(:disabled)")),errors=rows.filter(function(i){return i.dataset.affected==="1";});function sync(){const selected=rows.filter(function(i){return i.checked;}),selectedErrors=errors.filter(function(i){return i.checked;});all.disabled=!rows.length;all.checked=rows.length>0&&selected.length===rows.length;all.indeterminate=selected.length>0&&selected.length<rows.length;affected.disabled=!errors.length;affected.checked=errors.length>0&&selectedErrors.length===errors.length&&selected.length===errors.length;affected.indeterminate=selectedErrors.length>0&&!affected.checked;summary.textContent=selected.length+" of "+rows.length+" eligible orders selected · all review pages";}all.addEventListener("change",function(){const checked=all.checked;rows.forEach(function(i){i.checked=checked;});sync();});affected.addEventListener("change",function(){const checked=affected.checked;rows.forEach(function(i){i.checked=checked&&i.dataset.affected==="1";});sync();});rows.forEach(function(i){i.addEventListener("change",sync);});form.addEventListener("submit",function(){form.elements.selection_json.value=JSON.stringify(rows.filter(function(i){return i.checked;}).map(function(i){return i.value;}));});sync();});</script>';
}
